set.seed(42)
y <- ts(rnorm(24), frequency=12)
x <- ts(rnorm(24), frequency=12)
fit <- arima0(y, xreg=x, seasonal=list(order=c(0,1,0)))
print(fit)
print(fit$arma)
print(c(n=length(residuals(fit)), coefficients=length(fit$coef)))
fit.css <- arima0(y, xreg=x, seasonal=list(order=c(0,1,0)), method="CSS")
print(fit.css)
print(fit.css$arma)
print(c(n=length(residuals(fit.css)), coefficients=length(fit.css$coef)))
